use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (x_grid: Vec<Vec<f32>>, y_grid: Vec<Vec<f32>>)
    ensures
        // Shapes
        x_grid.len() == y.len(),
        y_grid.len() == y.len(),
        forall|i: int| 0 <= i < y.len() ==> x_grid[i].len() == x.len(),
        forall|i: int| 0 <= i < y.len() ==> y_grid[i].len() == x.len(),

        // Contents: each row of x_grid equals x
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> x_grid[i][j] == x[j],

        // Contents: each row of y_grid filled with y[i]
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> y_grid[i][j] == y[i],
{
    let rows = y.len();
    let cols = x.len();

    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &yv in &y
        invariant
            x_grid.len() == y_grid.len(),
            x_grid.len() <= y.len(),
            // shape invariants for already-built rows
            forall|i: int| 0 <= i < x_grid.len() ==> x_grid[i].len() == x.len(),
            forall|i: int| 0 <= i < y_grid.len() ==> y_grid[i].len() == x.len(),
            // content invariants for already-built rows
            forall|i: int, j: int|
                0 <= i < x_grid.len() && 0 <= j < x.len() ==> x_grid[i][j] == x[j],
            forall|i: int, j: int|
                0 <= i < y_grid.len() && 0 <= j < x.len() ==> y_grid[i][j] == y[i],
    {
        // Each row of x_grid is a copy of x
        x_grid.push(x.clone());

        // Each row of y_grid is filled with the corresponding y value
        y_grid.push(vec![yv; cols]);

        // Help the verifier connect the new yv to y[x_grid.len()-1]
        assert(yv == y[(x_grid.len() - 1) as int]);
    }

    (x_grid, y_grid)
}

} // verus!

